* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: #1e1e2f;
  color: #f0f0f5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.card {
  background: #2a2a40;
  border-radius: 1.5rem;
  padding: 2rem;
  max-width: 700px;
  width: 100%;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  border: 1px solid #3e3e5e;
}

h1 {
  font-size: 2rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
  color: #a78bfa;
}

.subtitle {
  color: #b0b0c8;
  margin-bottom: 1.5rem;
  font-size: 1rem;
}

.inputs {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

.input-group {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.input-group label {
  font-size: 0.85rem;
  font-weight: 500;
  color: #c0c0d8;
  margin-bottom: 0.25rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.input-group input {
  width: 100%;
  padding: 0.5rem 0.25rem;
  border: 2px solid #3e3e5e;
  border-radius: 0.75rem;
  background: #1e1e2f;
  color: #f0f0f5;
  font-size: 1.1rem;
  font-weight: 600;
  text-align: center;
  transition: border-color 0.2s, box-shadow 0.2s;
  outline: none;
}

.input-group input:hover {
  border-color: #7c6bb0;
}

.input-group input:focus-visible {
  border-color: #a78bfa;
  box-shadow: 0 0 0 3px rgba(167, 139, 250, 0.3);
}

.input-group input:active {
  background: #2a2a40;
}

.chart-container {
  background: #1e1e2f;
  border-radius: 1rem;
  padding: 1rem;
  margin-bottom: 1.5rem;
  border: 1px solid #3e3e5e;
}

canvas {
  display: block;
  width: 100%;
  height: auto;
  image-rendering: crisp-edges; /* pixelated */
  image-rendering: pixelated;
}

.stats {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 1rem;
  background: #1e1e2f;
  border-radius: 1rem;
  padding: 1rem 1.5rem;
  border: 1px solid #3e3e5e;
}

.stats p {
  font-size: 1.1rem;
  font-weight: 500;
}

.stats span {
  font-weight: 700;
  color: #a78bfa;
}

@media (max-width: 480px) {
  .card {
    padding: 1.5rem;
  }
  .inputs {
    gap: 0.25rem;
  }
  .input-group label {
    font-size: 0.7rem;
  }
  .input-group input {
    font-size: 0.9rem;
    padding: 0.4rem 0.1rem;
  }
  .stats {
    flex-direction: column;
    align-items: flex-start;
  }
}

const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const maxHours = 12;

const inputsContainer = document.getElementById('inputs');
const canvas = document.getElementById('chart');
const ctx = canvas.getContext('2d');
const averageSpan = document.getElementById('average');
const longestSpan = document.getElementById('longest');

// Create input fields for each day
const inputs = days.map((day, i) => {
  const group = document.createElement('div');
  group.className = 'input-group';
  const label = document.createElement('label');
  label.textContent = day;
  label.htmlFor = `day-${i}`;
  const input = document.createElement('input');
  input.type = 'number';
  input.id = `day-${i}`;
  input.min = '0';
  input.max = '12';
  input.step = '0.5';
  input.value = '0';
  input.setAttribute('aria-label', `Hours slept on ${day}`);
  input.addEventListener('input', updateChart);
  group.appendChild(label);
  group.appendChild(input);
  inputsContainer.appendChild(group);
  return input;
});

function getValues() {
  return inputs.map(input => {
    let val = parseFloat(input.value);
    if (isNaN(val)) val = 0;
    if (val < 0) val = 0;
    if (val > maxHours) val = maxHours;
    input.value = val; // clamp display
    return val;
  });
}

function drawChart(values) {
  const w = canvas.width;
  const h = canvas.height;
  const padding = { top: 20, right: 20, bottom: 30, left: 40 };
  const chartW = w - padding.left - padding.right;
  const chartH = h - padding.top - padding.bottom;

  ctx.clearRect(0, 0, w, h);

  // Pixel style: draw grid lines with small dashes
  ctx.strokeStyle = '#3e3e5e';
  ctx.lineWidth = 1;
  ctx.setLineDash([2, 4]);
  for (let i = 0; i <= 4; i++) {
    const y = padding.top + (chartH / 4) * i;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(w - padding.right, y);
    ctx.stroke();
  }
  ctx.setLineDash([]);

  // Y-axis labels
  ctx.fillStyle = '#b0b0c8';
  ctx.font = '10px system-ui, sans-serif';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  for (let i = 0; i <= 4; i++) {
    const val = maxHours - (maxHours / 4) * i;
    const y = padding.top + (chartH / 4) * i;
    ctx.fillText(val.toFixed(0), padding.left - 5, y);
  }

  // Bars
  const barWidth = chartW / 7 * 0.7;
  const gap = chartW / 7 * 0.3;
  const maxVal = Math.max(...values, 1);

  values.forEach((val, i) => {
    const barH = (val / maxHours) * chartH;
    const x = padding.left + i * (chartW / 7) + gap / 2;
    const y = padding.top + chartH - barH;

    // Determine if this is the longest night
    const isLongest = val === maxVal && val > 0;

    // Pixelated bar: draw with small squares to simulate pixel art
    const pixelSize = 4;
    const cols = Math.floor(barWidth / pixelSize);
    const rows = Math.floor(barH / pixelSize);

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        ctx.fillStyle = isLongest ? '#fbbf24' : '#a78bfa';
        ctx.fillRect(
          x + c * pixelSize + (barWidth - cols * pixelSize) / 2,
          y + r * pixelSize + (barH - rows * pixelSize) / 2,
          pixelSize,
          pixelSize
        );
      }
    }

    // If bar height is less than pixelSize, draw a single pixel
    if (rows === 0 && val > 0) {
      ctx.fillStyle = isLongest ? '#fbbf24' : '#a78bfa';
      ctx.fillRect(x + barWidth / 2 - 2, y + barH - 2, 4, 4);
    }

    // Day label
    ctx.fillStyle = '#b0b0c8';
    ctx.font = '10px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.fillText(days[i], x + barWidth / 2, padding.top + chartH + 5);
  });
}

function updateChart() {
  const values = getValues();
  drawChart(values);

  // Calculate average
  const sum = values.reduce((a, b) => a + b, 0);
  const avg = sum / 7;
  averageSpan.textContent = avg.toFixed(1);

  // Find longest night
  const maxVal = Math.max(...values);
  const longestIndex = values.indexOf(maxVal);
  if (maxVal > 0) {
    longestSpan.textContent = `${days[longestIndex]} (${maxVal} hours)`;
  } else {
    longestSpan.textContent = '—';
  }
}

// Initial draw
updateChart();
